settings.appCssStyle:
/* Description:
    - This CSS file is used to define the look and feel of the Fiori Horizon Morning theme in SAP Analytics Cloud.
    - This is the standard theme used for all BDC Insight Apps and is maintained by the BDC UX Team.
    - SAC Theme Name:
        - Insight App Fiori Morning Horizon Theme
    - Version:
        - 2.0.0 *** 08.July.2025 ***
    - Notes:
        - Variance Colors defined in UI Theme Dialog

/*------------------------------------------------------------------ */
/* ACCOUNT INPUT CONTROL-------------------------------------------- */
/*------------------------------------------------------------------ */

.saptheme .sap-custom-account-input-control-widget{ 
	background-color: #FFFFFF; 
}
.saptheme .sap-custom-account-input-control-main-label{ 
	color: #131e29;
	}
.saptheme .sap-custom-account-input-control-sub-label{ 
    color:#0070f2;
    font-weight:bold;
}
.saptheme .sap-custom-account-input-control-icon{ 
    color:#131e29; 
}
.saptheme .sap-custom-account-input-control-arrow{ 
    color:#0064d9;  
}
.saptheme .sap-custom-account-input-control-content{ 
    color:#131e29;  
}

/*------------------------------------------------------------------ */
/* BPC PLANNING SEQUENCE TRIGGER------------------------------------ */
/*------------------------------------------------------------------ */

/*------------------------------------------------------------------ */
/* BUTTON----------------------------------------------------------- */
/*------------------------------------------------------------------ */

/**Standard Button - using global CSS class**/
.saptheme .sap-custom-button{
	color: #0064d9;
	background-color: #FFFFFF;
	border-color: #BCC3CA;
	border-radius: 8px;
}
.saptheme .sap-custom-button:hover{
    color: #0064d9;
	background-color: #eaecee;
	border-color: #BCC3CA;	
}
.saptheme .sap-custom-button:active{
    color: #0064d9;
	background-color: #ffffff;
	border-color: #0064D9;	
}

/**Emphasized Button - .button--emphasized class**/
.button--emphasized .sap-custom-button{
    color:#FFFFFF;
    background-color:#0070F2;
    border-color: #0070F2;
	border-radius: 8px; 
}
.button--emphasized .sap-custom-button:hover{
    color:#FFFFFF;
    background-color:#0064d9;
    border-color:#0064d9;
}
.button--emphasized .sap-custom-button:active{
    color:#0064d9;
    background-color:#ffffff;
    border-color:#0064d9;
}

/*Lite Button - .button--lite class*/
.button--lite .sap-custom-button{
    color:#0064D9;
    background-color:transparent;
    border-color:transparent;
	border-radius:8px;
}
.button--lite .sap-custom-button:hover{
    color:#0064D9;
    background-color:#EAECEE;
    border-color:#BCC3CA;
}
.button--lite .sap-custom-button:active{
    color:#0064D9;
    background-color:#ffffff;
    border-color:#0064D9;
}

/*Shell Button / */
.button--shell .sap-custom-button{
    color:#1D2D3E;
    background-color:transparent;
    border-color:transparent;
	border-radius: 8px;
}
.button--shell .sap-custom-button:hover{
    color:#1D2D3E;
    background-color:#FFFFFF;
    border-color:#131e29;
}
.button--shell .sap-custom-button:active{
    color:#0070f2;
    background-color:#FFFFFF;
    border-color:#0064D9;
}

/**Accept Button/ Confirm / Positiv - .button--accept class**/
.button--accept .sap-custom-button{
    color:#256F3A;
    background-color:#EBF5CB;
    border-color: #DBEDA1;
	border-radius:8px;
}
.button--accept .sap-custom-button:hover{
    color:#256F3A;
    background-color:#e3f1b6;
    border-color:#e3f1b6;
}
.button--accept .sap-custom-button:active{
    color:#256F3A;
    background-color:#ffffff;
    border-color:#30914C;
}

/* Reject Button */
.button--reject .sap-custom-button{
    color:#AA0808;
    background-color:#FFD6E9;
    border-color:#ffc1df;
	border-radius:8px;
}
.button--reject .sap-custom-button:hover{
    color:#AA0808;
    background-color:#ffbcdc;
    border-color:#ffc1df;
}
.button--reject .sap-custom-button:active{
    color:#AA0808;
    background-color:#ffffff;
    border-color: #E90B0B;
}

/* Attention Button */
.button--attention .sap-custom-button{
    color:#b44f00;
    background-color:#FFF3B7;
    border-color:#FFEA84;
	border-radius:8px;
}
.button--attention .sap-custom-button:hover{
    color:#b44f00;
    background-color:#FFEF9E;
    border-color:#FFEF9E;
}
.button--attention .sap-custom-button:active{
    color:#b44f00;
    background-color:#ffffff;
    border-color: #DD6100;
}

/*Invisible button with Hover effect for Card on e.g. Landing Page*/
.button_card-pseudo-button .sap-custom-button-widget{
	background-color: transparent;
}
.button_card-pseudo-button .sap-custom-button{
	border-radius: 16px;
	background-color: transparent;
}
.button_card-pseudo-button .sap-custom-button:hover{
	border-radius: 16px;
	background-color: #7b96b210;
}
.button_card-pseudo-button .sap-custom-button:active{
	border-radius: 16px;
	background-color: transparent;
}

/* Panel for Dropdown as action button*/
.button__border--drop-down .sap-custom-panel-widget{
	border: thin solid #0064d9;
	background-color: #FFFFFF;
}


/* Dropdown as action button */
.button--drop-down .sap-custom-dropdown-trigger{
    border-radius: 8px;
    background-color: #FFFFFF;
    border-top: 1px solid #BCC3CA;
    border-right: 1px solid #BCC3CA;
    border-left: 1px solid #BCC3CA;
    border-bottom: 1px solid #BCC3CA;
} 
.button--drop-down .sap-custom-dropdown-trigger:hover{  
    border-radius: 8px;
    background-color: #EAECEF;
    border-top: 1px solid #BCC3CA;
    border-right: 1px solid #BCC3CA;
    border-left: 1px solid #BCC3CA;
    border-bottom: 1px solid #BCC3CA;
} 
.button--drop-down .sap-custom-dropdown-trigger:active{
    border-radius: 8px;
    background-color: #FFF;
    border-top: 1px solid #0064D9;
    border-right: 1px solid #0064D9;
    border-left: 1px solid #0064D9;
    border-bottom: 1px solid #0064D9;	
} 
.button--drop-down .sap-custom-dropdown-trigger-value{
    font-family: '72-Web';
    font-size: 14px;
    color: #0064D9;
    background-color:transparent; 
}
.button--drop-down .sap-custom-dropdown-trigger-arrow{
    font-size: 16px;
    background-color: #FFFFFF;
    color: #0064D9; 
    border-radius: 4px;
    padding: 0px 10px 0px 10px;
}
.button--drop-down .sap-custom-dropdown-trigger-arrow-expanded{
    background-color: #E5E5E5;
}
.button--drop-down .sap-custom-dropdown-trigger-arrow:hover{
    color: #1D2D3E;
    background-color: #EAECEF;
    border-radius: 4px;
    padding: 0px 10px 0px 10px;
}
.button--drop-down .sap-custom-dropdown-trigger-arrow:active{
    background-color: transparent; 
    color: #1D2D3E; 
    border-radius: 4px;
    padding: 0px 10px 0px 10px;
}
.button--drop-down .sap-custom-dropdown-item{
    color: #1D2D3E;
    font-weight: 400;

} 
.button--drop-down .sap-custom-dropdown-item:hover{ 
    color: #1D2D3E;
    font-weight: 400;
	background-color: #EAECEE;
} 
.button--drop-down .sap-custom-dropdown-item:active{
    color: #0064d9;
    font-weight: 400;
}
.button--drop-down .sap-custom-dropdown-selected-item{
    color: #1D2D3E;
    font-weight: 400;
    background-color: #edf5ff; 
}
.button--drop-down .sap-custom-dropdown-menu{
	border-radius: 8px;
	border: 1px solid #7A8691; 
}


/* Dimension Input Control as Button */
/* After applying this class to the respective widget, please also set up the following features in the styling panel */
/*  border = All Borders*/
/*  border color = transparent*/
/*  corner radius = 6px*/

.button--dimension-input-control .sap-custom-input-control-widget{
    border:thin solid #0064D9;
    background-color:transparent;
}
.button--dimension-input-control .sap-custom-input-control-sub-label{
    color: #0064D9;
    font-size: 14px;
}
.button--dimension-input-control .sap-custom-input-control-arrow{
    color: #0064D9;
}


/* Account Input Control as Button */
/* After applying this class to the respective widget, please also set up the following features in the styling panel */
/*  border = All Borders*/
/*  border color = transparent*/
/*  corner radius = 6px*/

.button--account-input-control .sap-custom-account-input-control-widget{
    border:thin solid #0064D9;
    background-color:transparent;
}
.button--account-input-control .sap-custom-account-input-control-sub-label{
    color: #0064D9;
    font-size: 14px;
}
.button--account-input-control .sap-custom-account-input-control-arrow{
    color: #0064D9;
}

/*------------------------------------------------------------------ */
/* CALCULATION INPUT CONTROL --------------------------------------- */
/*------------------------------------------------------------------ */

/*------------------------------------------------------------------ */
/* CHART  ---------------------------------------------------------- */
/*------------------------------------------------------------------ */
/* 
- no data label color defined so the data label color is dynamic 
  depending on the background if inside a bar
- Variance label need to be manually set because it's not available in CSS'
*/
/*--Continious Color Palette applied in the Theme based on Fiori Morning Colors-----*/

.saptheme .sap-custom-chart-title,
.chart_datalabels--contrast .sap-custom-chart-title,
.kpi_fixed-font-size .sap-custom-chart-title{ 
    font-family: '72-Web';
    font-size: 14px;
    color: #131e29;
    font-weight: 700;
}
.saptheme .sap-custom-chart-subtitle,
.chart_datalabels--contrast .sap-custom-chart-subtitle,
.kpi_fixed-font-size .sap-custom-chart-subtitle{ 
    font-family: '72-Web';
    font-size: 12px;
    color: #556B82;
    font-weight: 400;
}
.saptheme .sap-custom-chart-value-axis-title{
	font-family: '72-Web';
	font-size: 14px;
	fill: #131e29;
	font-weight: 300;
}
.saptheme .sap-custom-chart-category-axis-title{
	font-family: '72-Web';
	font-size: 14px;
	fill: #131e29;
	font-weight: 300;
}
.saptheme .sap-custom-chart-category-axis-label,
.chart_datalabels--contrast .sap-custom-chart-category-axis-label{ 
    font-family: '72-Web';
    font-size: 12px;
    fill: #131e29;
    font-weight: 400;
}
.saptheme .sap-custom-chart-category-axis-sublabel{
    font-family: '72-Web';
    font-size: 12px;
    fill: #131e29;
    font-weight: 300;
}
.saptheme .sap-custom-chart-value-axis-label,
.chart_datalabels--contrast .sap-custom-chart-value-axis-label{
	fill: #131e29;
}
.saptheme .sap-custom-chart-color-axis-label{
    font-family: '72-Web';
    font-size: 12px;
	fill: #131e29;
}
.saptheme .sap-custom-chart-value-axis-title-2{
	font-family: '72-Web';
	font-size: 14px;
	fill: #131e29;
	font-weight: 300;
}
.saptheme .sap-custom-chart-legend,
.chart_datalabels--contrast .sap-custom-chart-legend{
    font-family: '72-Web';
    font-size: 12px;
	fill: #131e29;
}
.saptheme .sap-custom-chart-data-labels {
	font-size: 12px;
	font-weight: 400;
    /*no fill needed*/	
}
/*- chart_datalabels--contrast to ensure data label visbility on Stacked & Heatmap Charts --*/
.chart_datalabels--contrast .sap-custom-chart-data-labels { 
	font-weight: 400;
}
/*----------------------------------------------------------------------------------------*/
.saptheme .sap-custom-number-chart-primary-values{ /*no font-size defined so the font-size is adaptive*/
    font-family: '72-Web';
    font-weight: 400;
}
.saptheme .sap-custom-number-chart-primary-labels{
    font-family: '72-Web';
    font-size: 12px;
    color: #556B82;
}
.saptheme .sap-custom-number-chart-secondary-values{ /*no font-size defined so the font-size is adaptive*/
    font-family: '72-Web';
    font-weight: 400;
}
.saptheme .sap-custom-number-chart-secondary-labels{
    font-family: '72-Web';
    font-size: 12px;
	color: #556B82;
}
.saptheme .sap-custom-number-chart-primary-variance-titles{
	font-size: 12px;
}
.saptheme .sap-custom-number-chart-secondary-variance-titles{
	font-size: 12px;
}
.saptheme .sap-custom-chart-footer{ 
    font-family: '72-Web';
    font-size: 12px;
    color: #556B82;
    font-weight: 400;
}
.saptheme .sap-custom-chart-footer-placeholder{ 
    font-size: 12px;
    color: #556B82;
}
.saptheme .sap-custom-chart-reference-label{ 
    font-family: '72-Web';
    font-size: 12px;
    fill: #000000;
    font-weight: 400;
}
.saptheme .sap-custom-chart-time-series-vertical-grid-line{
	stroke: #E1E6EB;
}
.saptheme .sap-custom-chart-time-series-horizontal-grid-line{
	stroke: #E1E6EB;
}
.saptheme .sap-custom-chart-waterfall-connector-line{
	stroke: #000000;
}
.saptheme .sap-custom-chart-bullet-pointer{
	fill: #000000;
	stroke: #000000
}

/* CUSTOM CLASSES FOR NUMBER CHARTS: FIXED FONT SIZE */
/*------------------------------------------------------------------*/
/* KPI Charts with fixed font size */
.kpi_fixed-font-size .sap-custom-number-chart-primary-labels{
    font-family: '72-Web';
    font-size: 16px;
    color: #556B82;
}
.kpi_fixed-font-size .sap-custom-number-chart-secondary-labels{
    font-family: '72-Web';
    font-size: 14px;
    color: #556B82;
}
.kpi_fixed-font-size .sap-custom-number-chart-primary-values{
    font-family: '72-Web';
    font-size: 32px;
    font-weight: 400;
}
.kpi_fixed-font-size .sap-custom-number-chart-secondary-values{
    font-family: '72-Web';
    font-size: 16px;
    font-weight: 400;
}
