/*------------------------------------------------------------------ */
/* CHECKBOX GROUP--------------------------------------------------- */
/*------------------------------------------------------------------ */

.saptheme .sap-custom-checkbox-group-item:hover{ 
    background-color:#dcf3ff;
}
.saptheme .sap-custom-checkbox-group-item-label,
.checkBox_group .sap-custom-checkbox-group-item-label{
    color: #131E29;
    font-family: '72-Web';
	font-size: 14px;
}
.saptheme .sap-custom-checkbox-group-mark-inner,
.checkBox_group .sap-custom-checkbox-group-mark-inner{
    color: #0064D9;
} 
.saptheme .sap-custom-checkbox-group-mark-outer,
.checkBox_group .sap-custom-checkbox-group-mark-outer{
    border-color: #556b81;
    background-color: #fff;
}

