}
.saptheme .sap-custom-filter-line-menu-item:hover{ 
    color:#131e29;
    background-color: #eaecee;
}
.saptheme .sap-custom-filter-line-menu-item:active{
    color:#131e29;
    background-color: #dee2e5;
}
.saptheme .sap-custom-filter-line-menu-item-disabled{
    color: #131e2940;
}

