functionImplementations.logicGroupExpandCollapse:
if(ExpandCollapseButton.getText() === Icon_Library.getText("arrow_right")){
	/*sets the height of the expanded state*/
	LogicGroup.getLayout().setHeight(Height);
	/*changes the icon inside the button to the arrow down*/
	ExpandCollapseButton.setText(Icon_Library.getText("arrow_down"));
	/*makes the content of the logic group visible*/
	Content.setVisible(true);
	/*adapt header panel CSS to show bottom line*/
	LogicGroupHeader.setCssClass('logic-group__header');
} else {
	/*sets the height of the collapsed state*/
	LogicGroup.getLayout().setHeight(68);
	/*changes the icon inside the button to the arrow right*/
	ExpandCollapseButton.setText(Icon_Library.getText("arrow_right"));
	/*makes the content of the logic group invisible*/
	Content.setVisible(false);
	/*adapt header panel CSS to hide bottom line*/
	LogicGroupHeader.setCssClass('');
}

functionImplementations.twoSectionFullscreen:
if(fullscreen_btn.getText()===''){
	headerPanel.setVisible(false);
	detailPanel.getLayout().setTop(8);
	fullscreen_btn.setText('');
} else {
	headerPanel.setVisible(true);
	detailPanel.getLayout().setTop(headerPanel.getLayout().getHeight());
	fullscreen_btn.setText('');
}
